/**
 * sprite-wiring.ts — STAGED ONLY, NOT IMPORTED BY THE GAME.
 * Pokemon-parity fill slice 5 (2026-10-26). DO NOT import this file from
 * App.tsx, BattleView.tsx, or RosterView.tsx until the coordinator merges
 * it and Mars approves the wiring step. No commit, no PR, no repo edit was
 * made by this slice; this file lives under mochiichao-work staging only.
 *
 * Pokemon shape (from the real decomp files, FireRed first):
 *   front.png / back.png / icon.png / shiny.pal / footprint.png /
 *   overworld 4-dir walk / cry.wav — one slot per species.
 * Mochiichao replacement: the SAME slots, Mochiichao creatures/art/words in
 * Pokemon's slots. Only literal Pokemon species/characters/logos/dialogue
 * are swapped; systems, structure, and data shapes come over literally
 * (Mars, 2026-10-26 ~13:07).
 *
 * Live truth today (do not over-claim): 0/51 sets verified wired live.
 * fresh-start/src/lib/spriteSheets.ts imports ONLY dorowani (147) + gabu
 * (148) sheets; every other species renders CreaturePortrait's coloured
 * silhouette fallback + "Art in progress" label (itself menu-meta item #30).
 * Applying this module means: copy staged art into
 * fresh-start/src/assets/sprites/<slug>/, add one sheet def per slug to
 * spriteSheets.ts, and point BattleView (enemy=front, player=back) and
 * RosterView/CreaturePortrait (team=front/icon) at it. That application
 * step is the coordinator's, not this file's.
 *
 * Status vocabulary (per creature, per slot):
 *   WIRED-STAGED  = this module maps the slot to a staged source file.
 *                   "Wired" here means mapped-in-this-staged-module, NOT live.
 *   STAGED-UNWIRED = art exists staged but cannot be mapped yet (see note).
 *   MISSING       = no staged source exists; hook shape only, never invented.
 *   NO-FOOTPRINT  = canonically footless; MochiDex shows no footprint, by
 *                   design, not by omission (feet were never invented).
 */

export type WiringStatus = 'WIRED-STAGED' | 'STAGED-UNWIRED' | 'MISSING' | 'NO-FOOTPRINT';

export interface SpriteSlot { status: WiringStatus; stagedPath: string | null; note: string; }
export interface CreatureSpriteWiring {
  slug: string; wiringStatus: WiringStatus;
  battleFront: SpriteSlot; battleBack: SpriteSlot; icon: SpriteSlot;
  idle: SpriteSlot; hurt: SpriteSlot; attack: SpriteSlot;
  walk: SpriteSlot & { framesPng: number };
  shiny: SpriteSlot & { palette: string | null; source: string | null };
  footprint: SpriteSlot;
  cry: SpriteSlot; // hook only until audio exists
}

function slot(status: WiringStatus, stagedPath: string | null, note: string): SpriteSlot {
  return { status, stagedPath, note };
}

