export const SPRITE_WIRING_COUNTS = {
  creatures: 51,
  wiredStaged: 50,
  stagedUnwired: 1, // mechapion battle_back only — no back role assigned
  missingCreatureLevel: 0,
  battleFront: '50/51 mapped (strikechamp_unsuited_full from game-ready, not lock-verified)',
  battleBack: '50/51 mapped (mechapion STAGED-UNWIRED)',
  icons: '51/51 mapped (Mars-approved 41/51 = 80%; 10 derived head-crops await Mars)',
  idle: '51/51', hurt: '51/51', attack: '51/51',
  shinyV2: '51/51 fronts + 51/51 palettes (17 sources changed vs old shiny, 34 unchanged)',
  footprints: '37/51 = 73% mapped; 14/51 = 27% NO-FOOTPRINT with reasons',
  walkDirsPresent: '50/51 = 98%',
  walkFull8Plus: '42/50 = 84%',
  walkPartialByDesign: '8/50 = 16%',
  cryWired: '0/51 = 0%',
  liveWiredVerified: '0/51 = 0%',
  titleSecondActionShots: 'staged 10/10 = 100%; wired live 0/10 = 0%',
} as const;

/** BattleView mapping (Pokemon slots): enemy battler = battleFront, player battler = battleBack. */
export function getBattleSprite(slug: string, side: 'enemy' | 'player'): SpriteSlot {
  const w = CREATURE_SPRITE_WIRING[slug];
  if (!w) return slot('MISSING', null, 'Unknown slug — never fall back to a Pokemon sprite.');
  return side === 'enemy' ? w.battleFront : w.battleBack;
}

/** Team / party mapping (RosterView + CreaturePortrait): list rows = icon, detail pane = battleFront. */
export function getTeamSprite(slug: string, view: 'icon' | 'front'): SpriteSlot {
  const w = CREATURE_SPRITE_WIRING[slug];
  if (!w) return slot('MISSING', null, 'Unknown slug — never fall back to a Pokemon sprite.');
  return view === 'icon' ? w.icon : w.battleFront;
}

/** Shiny mapping (Pokemon's own method: palette swap, not new art). SHINY-ON toggles this slot; if a creature's shiny is ever missing, show the normal front — never a placeholder caption. */
export function getShinyFront(slug: string): SpriteSlot {
  const w = CREATURE_SPRITE_WIRING[slug];
  if (!w) return slot('MISSING', null, 'Unknown slug.');
  return w.shiny;
}

/** MochiDex footprint mapping (Pokemon footprint.png slot). NO-FOOTPRINT creatures return their reason, not an invented print. */
export function getFootprint(slug: string): SpriteSlot {
  const w = CREATURE_SPRITE_WIRING[slug];
  if (!w) return slot('MISSING', null, 'Unknown slug.');
  return w.footprint;
}

/** Cry hook shape ONLY. Returns null for all 51 slugs today because cry audio is 0/51. Callers must handle null as silence, not as an error and not as a substitute sound. No audio is generated, fetched, or invented by this function. */
export function getCry(_slug: string): null {
  return null;
}
